mapper.select:
SELECT DATE_FORMAT(entry_time, #{groupBy}) as time_period, COUNT(DISTINCT visitor_id) as visitor_count, AVG(stay_duration) as avg_stay_duration, COUNT(DISTINCT source_city) as source_city_count, SUM(CASE WHEN gender = 'M' THEN 1 ELSE 0 END) as male_count, SUM(CASE WHEN gender = 'F' THEN 1 ELSE 0 END) as female_count, AVG(age) as avg_age FROM t_visitor_record WHERE area_id = #{areaId}
AND entry_time >= #{startTime}
AND entry_time <= #{endTime}
AND visitor_type = #{visitorType}
AND deleted = 0 GROUP BY DATE_FORMAT(entry_time, #{groupBy}) ORDER BY time_period
